  author_id: string | null;
  title: string;
  slug: string;
  excerpt: string;
  content: string;
  category: string;
  hero_image_url: string | null;
  external_url: string | null;
  external_label: string | null;
  status: PostStatus;
  is_featured: boolean;
  seo_title: string | null;
